    for i in range(n):
        temp = int(s[i])
        if pos[temp]==-1:
            pos[temp] = i 
    flag1 = [[[False for i in range(10)] for i in range(10)] for i in range(10)]
    flag2 = [[False for i in range(10)] for i in range(10)]
