def kanou(s, i1, i2, i3):
    target = [i1, i2, i3]
    target_iter = target.__iter__()
    now = next(target_iter)
    for c in s:
        if c == now:
            try:
                now = next(target_iter)
            except StopIteration:
                return True
    return False

