        for i in range(N-2):
            edge[b[i]].append(b[i+1])
            IN[b[i+1]] += 1

    def t_sort():
        que = deque([i for i,c in enumerate(IN) if c == 0])
        l = []
        while que:
            now = que.popleft()
            l.append(now)
            for fol in edge[now]:
                IN[fol] -= 1
                if IN[fol] == 0:
                    que.append(fol)
        if len(l) != (N*(N-1))//2:
            print(-1)
            exit()
        return l

    ts = t_sort()
    dp = [1]*((N*(N-1))//2)
    for now in ts:
