        if len(check[i-1]) < len(check[i]):
            exit(print(0))
        # check[i]がcheck[i-1]のなかで何番目か調べる
        for j in range(len(check[i])):
            d = bisect_right(check[i-1],check[i][j])
            if d < j:
                exit(print(0))
            ans *= d-j
            ans %= p
            # print(ans)
    print(ans)

