N, M = map(int, input().split())
S = list(input().rstrip())

def cost(S):
    minCost = [-1]*(N+1)
    minCost[0] = 0
    ind = 1
    for i,s in enumerate(S):
        if s == "1":
            continue
        while i < ind <= min(i+M, N):
            if S[ind] == "0":
                minCost[ind] = minCost[i] + 1
            ind += 1
    return minCost

