def dfs(nh, nw, color):
    direction = [(1, 0), (0, 1), (-1, 0), (0, -1)]
    C[nh][nw] = color
    for dh, dw in direction:
        if not ((0 <= nh + dh < H) and (0 <= nw + dw < W)):
            continue
        if C[nh + dh][nw + dw] != 0:
            continue
        if G[nh][nw] == G[nh + dh][nw + dw]:
            continue
        C[nh + dh][nw + dw] = color
        dfs(nh + dh, nw + dw, -color)


