import sys


def warshall_floyd(A):
    #d[i][j]: iからjへの最短距離
    l = len(A)
    for k in range(l):
        for i in range(l):
            for j in range(l):
                A[i][j] = min(A[i][j], A[i][k] + A[k][j])
    return A


def solve(H: int, W: int, c: "List[List[int]]", A: "List[List[int]]"):
    c = warshall_floyd(c)
    cost = 0
    for h in range(H):
        for w in range(W):
            if A[h][w] != -1:
                cost += c[A[h][w]][1]
    print(cost)
    return


