            c[key] -= 2
            d[2] -= 1

    for key in keys:
        if c[key] % 4 == 0:
            d[4] -= c[key] // 4
            c[key] = 0

    while d[2] > 0:
        d[2] -= 2
        d[4] += 1

    if d[1] == d[2] == d[4] == 0:
