def shellSort(A, n):

    def func(m):
        if m == 0:
            return 1
        else:
            return func(m-1)*3 + 1

    G = []
    i = 0

    while True:
        gi = func(i)
        if gi <= n:
            G.append(gi)
            i += 1
        else:
            break

    G = G[::-1]
    for g in G:
        insertionSort(A, n , g)

    return A, G


