def solve(N, A):
    A.sort()
    n = N-1
    p = bisect_left(A, A[n] / 2)
    low = max(0, p - 1)
    high = min(N - 1, p)
    if n == high:
        return "%d %d" % (A[n], A[low])
    elif A[low] > A[n] - A[high]:
        return "%d %d" % (A[n], A[low])
    else:
        return "%d %d" % (A[n], A[high])


