    return readline().strip().split()


def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap



@mt
def slv(M, K):
    if K >= 2**(M+1):
        return [-1]

    if K == 0:
        ans = []
        for i in range(2**M):
            ans.append(i)
            ans.append(i)
        return ans

    p = []
    done = set()
    for a in range(2**M):
        if a in done:
            continue
        b = K ^ a
        if b >= 2**M:
            return [-1]
        p.append((a, b))
        done.add(a)
        done.add(b)

    if len(p) % 2 != 0:
        return [-1]

    ans = []
    for i in range(0, len(p), 2):
        a, b = p[i]
        c, d = p[i+1]
        ans.append(a)
        ans.append(b)
        ans.append(c)
        ans.append(d)
        ans.append(b)
        ans.append(a)
        ans.append(d)
        ans.append(c)

    return ans



