def bfs(n,A):
    color = [-1]*n
    d = [-1]*n
    Q = []
    d[0] = 0
    Q.append(0)
    while(True):
        if len(Q)==0:
            break
        u = Q.pop(0)
        for i in A[u][2:]:
            if color[i-1] == -1:
                color[i-1] = 0
                d[i-1] = d[u]+1
                Q.append(i-1)
        color[u] = 1
    return color, d    

