            nx = x + dx
            if ny < 0 or ny >= H or nx < 0 or nx >= W:
                continue
            if s_l[ny][nx] == "." and not results[ny][nx]:
                queue.append((ny, nx))
                results[ny][nx] = True
    if queue:
        count += 1

print(count)

