        n += 1
    # 後は間を抜いて、ジャストN点になるよう調整していく
    d = n * (n + 1) // 2 - N
    solve = [1] * (n + 1)  # 1-indexで扱うので0番目は使わない
    for i in range(n, 0, -1):
        if i <= d:
            d -= i
            solve[i] = 0
        if d == 0:
            break
    for i in range(1, n + 1):
        if solve[i] == 1:
