    c = (c & 0x5555555555555555) + (c >> 1 & 0x5555555555555555)
    c = (c & 0x3333333333333333) + (c >> 2 & 0x3333333333333333)
    c = (c + (c >> 4)) & 0x0F0F0F0F0F0F0F0F
