def binary_search(a,n):
    low = 0
    high = len(a) - 1
    while low <= high:
        mid = (low + high) // 2
        index = a[mid]
        if index == n:
            return True
        elif index < n:
            low = mid+1
        else:
            high = mid -1
    return False

