def dijkstra(G, s):
    # sを始点としてすべての点への最短距離を求める
    inf = 10**18
    n = len(G)
    D = [inf for i in range(n)]
    D[s] = 0
    Q = [s]
    while Q:
        x = Q.pop()
        for y in G[x]:
            if D[y] > D[x] + 1:
                D[y] = D[x] + 1
                Q.append(y)
    return D


