def isvalid(n, H, N, A, B):
    alive = []
    for i in range(len(H)):
        if H[i] - n*B > 0:
            alive.append(H[i]-n*B)
    count = 0
    for v in alive:
        if v % (A-B) == 0:
            count += v //(A-B)
        else:
            count += v //(A-B) + 1
    if count <= n:
        return True
    else:
        return False



