    time = 0
    if dia[sta][1] > start_time:
        time += dia[sta][1] - start_time
    elif start_time % dia[sta][2] != 0:
        time += dia[sta][2] * (start_time // dia[sta][2] + 1) - start_time
    time += dia[sta][0]
    return time

