def scores(card1, card2):
    """returns scores of a card game.

    >>> scores('cat', 'dog')
    (0, 3)
    >>> scores('fish', 'fish')
    (1, 1)
    >>> scores('tiger', 'lion')
    (3, 0)
    """
    if card1 == card2:
        return (1, 1)
    elif card1 > card2:
        return (3, 0)
    else:
        return (0, 3)


