    alphabets = "abcdefghijklmnopqrstuvwxyz"

    s = []

    def dfs(i):
        """i種類の文字から選んで、sの末尾に追加する
        """
        if len(s) == N:
            q.append(''.join(s))
        else:
            for j, a in enumerate(alphabets[:i-1]):
                s.append(a)
                dfs(i)
                s.pop()
            a = alphabets[i-1]
            s.append(a)
            dfs(i+1)
            s.pop()

    dfs(1)
    return q

def solve(N):
    for s in standalize(N):
        print(s)

