import math


def calc_minkowski_distance(x1, x2, p):
    """calc L_p norm(finite dimension)

    Args:
        x1: vector1
        x2: vector2
        p: p in L_p

    Returns:
        L_p distance between x1 and x2 (float)
    """
    if p == "inf":
        return max([math.fabs(x[0] - x[1]) for x in zip(x1, x2)])
    else:
        return math.pow(sum([math.pow(math.fabs(x[0] - x[1]), p) for x in zip(x1, x2)]), 1.0 / p)


