def calc(n, x, y):
    ret = []
    patterns = [1, 2, 3]
    for pattern in patterns:
        sum = 0
        for i in range(0, n):
            sum += (abs(x[i] - y[i])) ** pattern
        ret.append(sum ** (1 / pattern))

    last = 0
    for i in range(0, n):
        last = max(last, abs(x[i] - y[i]))
    ret.append(last)

    return ret


