import copy

def gen_mono_inc_seqs(N, M, cur_list, cur_len):
    if cur_len == N:
        return cur_list

    result = []
    for l in cur_list:
        last_val = l[len(l)-1]
        for i in range(last_val, M+1):
            tmp = copy.copy(l)
            tmp.append(i)
            result.append(tmp)

    return gen_mono_inc_seqs(N, M, result, cur_len+1)


