def solve(N, K, A):
    # 先手が勝つ: True, 先手が負ける: False
    dp = [False for i in range(K+1)]
    # 石が残りmin(A)未満のとき、操作不可のため負け
    for i in range(min(A)):
        dp[i] = False
    for i in range(min(A), K+1):
        for a in A:
            if i - a >= 0:
                dp[i] |= not dp[i - a]
    return 'First' if dp[K] else 'Second'


