def dfs(G, i):
    seen = set([i])
    stack = [i]
    cnt = 0
    while stack:
        node = stack.pop()
        cnt += 1
        for _n in G[node]:
            if _n not in seen:
                seen.add(_n)
                stack.append(_n)
    return cnt


