def rle(t):
    tmp2, count_, ans_ = t[0], 1, []
    for i_ in range(1, len(t)):
        if tmp2 == t[i_]:
            count_ += 1
        else:
            ans_.append([tmp2, count_])
            tmp2 = t[i_]
            count_ = 1
    ans_.append([tmp2, count_])
    return ans_


