def dijkstra(v, G):
    import heapq

    ret = [10 ** 10] * len(G)
    ret[v] = 0
    q = [(ret[i], i) for i in range(len(G))]
    heapq.heapify(q)

    while len(q):
        tmpr, u = heapq.heappop(q)
        if tmpr == ret[u]:
            for w in G[u]:
                if ret[w] > ret[u] + 1:
                    ret[w] = ret[u] + 1
                    heapq.heappush(q, (ret[w], w))
    return ret


