def resolve():
    N = I()
    A = [I() for _ in range(N)]

    # 奇数個の山同士を相殺して偶数個の山にした後同数字ペアを作る
    # 奇数個の山の間に0個の山が無ければ全て取れる
    # 言い換えれば0個の山の間は0,1個残しで取り切れる
    A_cum = [0] * (N + 1)
    zero = [0]
    for i in range(N):
        A_cum[i+1] = A_cum[i] + A[i]
        if A[i] == 0:
            zero.append(i)
    zero.append(N)

    ans = 0
    for i in range(len(zero) - 1):
        ans += (A_cum[zero[i+1]] - A_cum[zero[i]]) // 2

    print(ans)

