def sieve_of_eratosthenes(n):
  primes = [2]
  cands = numpy.array(list(range(3, n+1, 2)), dtype=numpy.int)
  while len(cands) != 0:
    prime = primes[-1]
    cands = cands[cands % prime != 0]
    if len(cands) == 0:
      break
    primes.append(cands[0])
  return primes

